-- United Arab Emirates deep-dive content translations (ES/DE/FR)

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'es', 'Modelo descentralizado de 5 esquinas (DCTCE)', 'Esta página de análisis refleja la orientación técnica disponible públicamente a partir de julio de 2026 y se proporciona con fines informativos generales, no como asesoramiento legal o fiscal. Las especificaciones técnicas de PINT AE, el registro de acreditación de ASP y la aplicación de sanciones siguen evolucionando — confirme los requisitos actuales directamente con el Ministerio de Finanzas de los EAU o la Autoridad Federal de Impuestos antes de construir una integración.', 'Los EAU construyeron su marco de facturación electrónica de forma inusualmente metódica — consulta del diccionario de datos, luego legislación, luego acreditación de ASP, luego un piloto voluntario, todo antes de que comience el propio mandato.', 'PINT AE es una especificación genuinamente extensa — más de 135 elementos de datos, organizados deliberadamente en capas para equilibrar la interoperabilidad global de Peppol con las normas de IVA específicas de los EAU.', 'El modelo "de 5 esquinas" DCTCE de los EAU combina el intercambio al estilo Peppol con el reporte fiscal automático — no hay un paso de declaración de IVA separado para las transacciones facturadas electrónicamente.', 'No asuma que su ASP se encarga de todo por sí solo — la alineación interna de TI y finanzas se señala explícitamente como una brecha común.', 'La Decisión del Gabinete n.º 106 de 2025 define seis categorías específicas de infracciones — algunas limitadas mensualmente, otras acumulándose diariamente sin límite.' FROM countries WHERE name_en = 'United Arab Emirates';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'de', 'Dezentrales 5-Ecken-Modell (DCTCE)', 'Diese Detailseite spiegelt öffentlich verfügbare technische Hinweise mit Stand Juli 2026 wider und dient allgemeinen Informationszwecken, nicht der Rechts- oder Steuerberatung. Die technischen Spezifikationen von PINT AE, das ASP-Akkreditierungsregister und die Durchsetzung von Bußgeldern entwickeln sich weiter — bestätigen Sie aktuelle Anforderungen direkt beim Finanzministerium der VAE oder der Federal Tax Authority, bevor Sie eine Integration aufbauen.', 'Die VAE haben ihren E-Invoicing-Rahmen ungewöhnlich methodisch aufgebaut — Konsultation zum Datenwörterbuch, dann Gesetzgebung, dann ASP-Akkreditierung, dann ein freiwilliges Pilotprojekt, alles noch vor Beginn des eigentlichen Mandats.', 'PINT AE ist eine wirklich umfangreiche Spezifikation — über 135 Datenelemente, bewusst geschichtet, um die globale Peppol-Interoperabilität mit VAE-spezifischen Mehrwertsteuerregeln in Einklang zu bringen.', 'Das "5-Ecken"-DCTCE-Modell der VAE bündelt den Peppol-artigen Austausch mit automatischer Steuermeldung — es gibt keinen separaten Mehrwertsteuer-Meldeschritt für elektronisch fakturierte Transaktionen.', 'Gehen Sie nicht davon aus, dass Ihr ASP allein alles erledigt — die interne Abstimmung zwischen IT und Finanzen wird ausdrücklich als häufige Lücke genannt.', 'Kabinettsbeschluss Nr. 106 von 2025 definiert sechs spezifische Verstoßkategorien — einige monatlich gedeckelt, andere täglich ohne Obergrenze anwachsend.' FROM countries WHERE name_en = 'United Arab Emirates';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'fr', 'Modèle décentralisé à 5 coins (DCTCE)', 'Cette page d''analyse reflète les orientations techniques publiquement disponibles en date de juillet 2026 et est fournie à titre informatif général, non comme un avis juridique ou fiscal. Les spécifications techniques de PINT AE, le registre d''accréditation des ASP et l''application des sanctions continuent d''évoluer — confirmez les exigences actuelles directement auprès du ministère des Finances des EAU ou de l''Autorité fédérale des impôts avant de construire une intégration.', 'Les EAU ont construit leur cadre de facturation électronique de façon inhabituellement méthodique — consultation sur le dictionnaire de données, puis législation, puis accréditation des ASP, puis un pilote volontaire, le tout avant même le début du mandat lui-même.', 'PINT AE est une spécification véritablement volumineuse — plus de 135 éléments de données, délibérément superposés pour concilier l''interopérabilité Peppol mondiale avec les règles de TVA propres aux EAU.', 'Le modèle DCTCE « à 5 coins » des EAU associe un échange de type Peppol à une déclaration fiscale automatique — il n''existe aucune étape distincte de déclaration de TVA pour les transactions facturées électroniquement.', 'Ne présumez pas que votre ASP gère tout à lui seul — l''alignement interne entre l''IT et la finance est explicitement signalé comme une lacune fréquente.', 'La décision du Cabinet n° 106 de 2025 définit six catégories spécifiques d''infractions — certaines plafonnées mensuellement, d''autres s''accumulant quotidiennement sans limite.' FROM countries WHERE name_en = 'United Arab Emirates';

