INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Qué es PINT AE', '[["Significado completo", "Peppol International (EAU)"], ["Estándar base", "UBL, alineado con el Peppol PINT global"], ["Adopción legal", "Decisión Ministerial n.º 243 de 2025"]]', 'PINT AE es una extensión localizada, no un esquema completamente distinto — las empresas ya familiarizadas con Peppol PINT en otros lugares tienen una ventaja real.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'United Arab Emirates' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Tres capas de contenido', '[["Contenido central compartido", "Elementos universales de Peppol PINT (identificadores, fechas, partes, totales)"], ["Contenido alineado", "Campos estandarizados internacionalmente mapeados a las clasificaciones de los EAU (categorías de IVA, lógica fiscal, pago)"], ["Extensión de los EAU", "Campos específicos de los EAU más allá de la base global"]]', 'Este diseño en capas es precisamente lo que preserva la interoperabilidad básica en toda la red global de Peppol, al tiempo que aplica las normas de IVA propias de los EAU.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'United Arab Emirates' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Número de campos y alcance', '[["Elementos totales", "135+ (obligatorios, condicionales, opcionales)"], ["Factura fiscal estándar", "~50–51 campos obligatorios"], ["Escenarios admitidos", "Estándar, tipo cero, inversión del sujeto pasivo, suministros en zona franca"]]', 'Los campos obligatorios ausentes o con formato incorrecto provocan el rechazo directo sin posibilidad de anulación manual — no existe una aceptación parcial ni un paso de corrección manual en la capa del ASP.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'United Arab Emirates' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Identificadores clave y contenido', '[["UUID", "Único por documento de factura"], ["A nivel de línea", "Tasa e importe de IVA por línea de factura"], ["Moneda", "Importe total de la factura en AED"], ["Seguridad", "Firma digital (aplicada por el ASP) + código QR"]]', 'Los PDF, documentos escaneados y facturas en papel no son explícitamente válidos bajo el mandato — solo cuenta el XML/JSON estructurado generado conforme a PINT AE.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'United Arab Emirates' AND dc.section = 'file_format' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Was PINT AE ist', '[["Vollständige Bedeutung", "Peppol International (VAE)"], ["Basisstandard", "UBL, ausgerichtet auf das globale Peppol PINT"], ["Rechtliche Übernahme", "Ministerialbeschluss Nr. 243 von 2025"]]', 'PINT AE ist eine lokalisierte Erweiterung, kein völlig eigenständiges Schema — Unternehmen, die mit Peppol PINT anderswo bereits vertraut sind, haben einen echten Vorsprung.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'United Arab Emirates' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Drei Inhaltsebenen', '[["Gemeinsamer Kerninhalt", "Universelle Peppol-PINT-Elemente (IDs, Daten, Parteien, Summen)"], ["Angeglichener Inhalt", "International standardisierte Felder, zugeordnet zu VAE-Klassifizierungen (Mehrwertsteuerkategorien, Steuerlogik, Zahlung)"], ["VAE-Erweiterung", "VAE-spezifische Felder über die globale Basis hinaus"]]', 'Dieses geschichtete Design ist genau das, was die grundlegende Interoperabilität im gesamten globalen Peppol-Netzwerk bewahrt und gleichzeitig VAE-spezifische Mehrwertsteuerregeln durchsetzt.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'United Arab Emirates' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Feldanzahl & Umfang', '[["Elemente insgesamt", "135+ (Pflicht-, bedingte, optionale Felder)"], ["Standardsteuerrechnung", "~50–51 Pflichtfelder"], ["Unterstützte Szenarien", "Standard, Nullsatz, Reverse Charge, Freizonenlieferungen"]]', 'Fehlende oder falsch formatierte Pflichtfelder führen zur vollständigen Ablehnung ohne manuelle Überschreibung — es gibt keine Teilannahme oder manuellen Korrekturschritt auf ASP-Ebene.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'United Arab Emirates' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Wichtige Kennungen & Inhalt', '[["UUID", "Eindeutig pro Rechnungsdokument"], ["Zeilenebene", "Mehrwertsteuersatz und -betrag pro Rechnungsposition"], ["Währung", "Gesamtrechnungsbetrag in AED"], ["Sicherheit", "Digitale Signatur (vom ASP angebracht) + QR-Code"]]', 'PDFs, gescannte Dokumente und Papierrechnungen sind unter dem Mandat ausdrücklich nicht gültig — nur strukturiertes, nach PINT AE erzeugtes XML/JSON zählt.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'United Arab Emirates' AND dc.section = 'file_format' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Ce qu''est PINT AE', '[["Signification complète", "Peppol International (EAU)"], ["Norme de base", "UBL, aligné sur le Peppol PINT mondial"], ["Adoption légale", "Décision ministérielle n° 243 de 2025"]]', 'PINT AE est une extension localisée, pas un schéma entièrement distinct — les entreprises déjà familières avec Peppol PINT ailleurs disposent d''une réelle longueur d''avance.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'United Arab Emirates' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Trois couches de contenu', '[["Contenu central partagé", "Éléments Peppol PINT universels (identifiants, dates, parties, totaux)"], ["Contenu aligné", "Champs normalisés à l''international mappés sur les classifications des EAU (catégories de TVA, logique fiscale, paiement)"], ["Extension EAU", "Champs propres aux EAU au-delà de la base mondiale"]]', 'Cette conception en couches est précisément ce qui préserve l''interopérabilité de base à travers le réseau Peppol mondial tout en appliquant les règles de TVA propres aux EAU.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'United Arab Emirates' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Nombre de champs et champ d''application', '[["Éléments totaux", "135+ (obligatoires, conditionnels, facultatifs)"], ["Facture fiscale standard", "~50-51 champs obligatoires"], ["Scénarios pris en charge", "Standard, taux zéro, autoliquidation, livraisons en zone franche"]]', 'Les champs obligatoires manquants ou mal formatés entraînent un rejet pur et simple sans possibilité de dérogation manuelle — il n''existe aucune acceptation partielle ni étape de correction manuelle au niveau de l''ASP.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'United Arab Emirates' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Identifiants clés et contenu', '[["UUID", "Unique par document de facture"], ["Au niveau des lignes", "Taux et montant de TVA par ligne de facture"], ["Devise", "Montant total de la facture en AED"], ["Sécurité", "Signature électronique (apposée par l''ASP) + code QR"]]', 'Les PDF, documents numérisés et factures papier ne sont explicitement pas valables sous le mandat — seul le XML/JSON structuré généré conformément à PINT AE est valable.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'United Arab Emirates' AND dc.section = 'file_format' AND dc.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'es', 'Las cinco esquinas', 'Cada factura pasa por las cinco en secuencia:', 'La esquina 5 (la FTA) recibe automáticamente un informe de Documento de Datos Fiscales (TDD) de ambos ASP — los datos fiscales fluyen a la autoridad con cada factura intercambiada, sin necesidad de un paso de declaración de IVA independiente.' FROM deep_dive_lifecycle_cards lc JOIN countries co ON co.id = lc.country_id WHERE co.name_en = 'United Arab Emirates' AND lc.section = 'scope_transmission' AND lc.sort_order = 3;
