INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'de', 'Die fünf Ecken', 'Jede Rechnung durchläuft alle fünf der Reihe nach:', 'Ecke 5 (die FTA) erhält automatisch einen Tax Data Document (TDD)-Bericht von beiden ASPs — Steuerdaten fließen mit jeder ausgetauschten Rechnung an die Behörde, ohne separaten Mehrwertsteuer-Meldeschritt.' FROM deep_dive_lifecycle_cards lc JOIN countries co ON co.id = lc.country_id WHERE co.name_en = 'United Arab Emirates' AND lc.section = 'scope_transmission' AND lc.sort_order = 3;
