INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'de', 'FTA' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lcc ON lcc.id = ls.card_id JOIN countries co ON co.id = lcc.country_id WHERE co.name_en = 'United Arab Emirates' AND lcc.section = 'scope_transmission' AND lcc.sort_order = 3 AND ls.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'fr', 'Les cinq coins', 'Chaque facture passe par les cinq dans l''ordre :', 'Le coin 5 (la FTA) reçoit automatiquement un rapport de document de données fiscales (TDD) des deux ASP — les données fiscales parviennent à l''administration à chaque échange de facture, sans étape de déclaration de TVA distincte.' FROM deep_dive_lifecycle_cards lc JOIN countries co ON co.id = lc.country_id WHERE co.name_en = 'United Arab Emirates' AND lc.section = 'scope_transmission' AND lc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'fr', 'Fournisseur' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lcc ON lcc.id = ls.card_id JOIN countries co ON co.id = lcc.country_id WHERE co.name_en = 'United Arab Emirates' AND lcc.section = 'scope_transmission' AND lcc.sort_order = 3 AND ls.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'fr', 'ASP du fournisseur' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lcc ON lcc.id = ls.card_id JOIN countries co ON co.id = lcc.country_id WHERE co.name_en = 'United Arab Emirates' AND lcc.section = 'scope_transmission' AND lcc.sort_order = 3 AND ls.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'fr', 'ASP de l''acheteur' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lcc ON lcc.id = ls.card_id JOIN countries co ON co.id = lcc.country_id WHERE co.name_en = 'United Arab Emirates' AND lcc.section = 'scope_transmission' AND lcc.sort_order = 3 AND ls.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'fr', 'Acheteur' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lcc ON lcc.id = ls.card_id JOIN countries co ON co.id = lcc.country_id WHERE co.name_en = 'United Arab Emirates' AND lcc.section = 'scope_transmission' AND lcc.sort_order = 3 AND ls.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'fr', 'FTA' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lcc ON lcc.id = ls.card_id JOIN countries co ON co.id = lcc.country_id WHERE co.name_en = 'United Arab Emirates' AND lcc.section = 'scope_transmission' AND lcc.sort_order = 3 AND ls.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Qué hace realmente su ASP', '[["Validación", "Comprueba el XML frente al esquema PINT AE"], ["Conversión", "Convierte los datos de facturación en XML PINT AE conforme"], ["Seguridad", "Aplica la firma digital y el código QR"], ["Transmisión", "Envía a través de la red Peppol al ASP del comprador"]]', 'Su ERP solo necesita generar los datos subyacentes de la factura — el ASP se encarga de la conversión, la firma y la entrega, pero esa división del trabajo hace que elegir el ASP adecuado sea realmente importante.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'United Arab Emirates' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Proceso de acreditación del ASP', '[["1. Solicitud", "Presentada a través del portal del MoF"], ["2–3. Pruebas", "Comprobaciones de interoperabilidad previas a la aprobación, seguidas de pruebas de producción de extremo a extremo"], ["4. Certificación", "Certificado ISO, seguro y verificación de cumplimiento"], ["5. Credencial", "Emisión del certificado PKI de Peppol"], ["6. Acreditación", "Concedida por 2 años, renovable"]]', 'Verifique siempre la acreditación de un proveedor directamente en el registro público oficial del MoF — no confíe en la afirmación de acreditación que haga el propio proveedor en su publicidad.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'United Arab Emirates' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Sin carga directa en el portal de la FTA', '[["Modelo", "Descentralizado — las facturas fluyen a través de Peppol/ASP, nunca directamente a un portal gubernamental"]]', 'Este es el contraste definitorio con Arabia Saudí, su vecino: no hay ningún portal de compensación gubernamental al que cargar — todo pasa a través de su proveedor de servicios acreditado.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'United Arab Emirates' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Was Ihr ASP tatsächlich tut', '[["Validierung", "Prüft XML gegen das PINT-AE-Schema"], ["Umwandlung", "Wandelt Rechnungsdaten in konformes PINT-AE-XML um"], ["Sicherheit", "Bringt digitale Signatur und QR-Code an"], ["Übertragung", "Sendet über das Peppol-Netzwerk an den ASP des Käufers"]]', 'Ihr ERP muss nur die zugrunde liegenden Rechnungsdaten erzeugen — der ASP übernimmt Umwandlung, Signierung und Zustellung, aber diese Arbeitsteilung bedeutet, dass die Wahl des richtigen ASP wirklich wichtig ist.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'United Arab Emirates' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'ASP-Akkreditierungsprozess', '[["1. Antrag", "Über das MoF-Portal eingereicht"], ["2.–3. Tests", "Interoperabilitätsprüfungen vor der Genehmigung, dann End-to-End-Tests in Produktion"], ["4. Zertifizierung", "ISO-Zertifikat, Versicherung und Compliance-Prüfung"], ["5. Berechtigungsnachweis", "Ausstellung des Peppol-PKI-Zertifikats"], ["6. Akkreditierung", "Für 2 Jahre erteilt, verlängerbar"]]', 'Überprüfen Sie die Akkreditierung eines Anbieters immer direkt im offiziellen öffentlichen Register des MoF — verlassen Sie sich nicht auf die eigene Marketingaussage eines Anbieters zur Akkreditierung.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'United Arab Emirates' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Kein direkter FTA-Portal-Upload', '[["Modell", "Dezentral — Rechnungen fließen über Peppol/ASP, nie direkt an ein Regierungsportal"]]', 'Dies ist der entscheidende Kontrast zum benachbarten Saudi-Arabien: Es gibt kein staatliches Freigabeportal zum Hochladen — alles läuft über Ihren akkreditierten Dienstanbieter.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'United Arab Emirates' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Ce que votre ASP fait réellement', '[["Validation", "Vérifie le XML par rapport au schéma PINT AE"], ["Conversion", "Convertit les données de facturation en XML PINT AE conforme"], ["Sécurité", "Applique la signature électronique et le code QR"], ["Transmission", "Envoie via le réseau Peppol vers l''ASP de l''acheteur"]]', 'Votre ERP n''a besoin que de générer les données de facture sous-jacentes — l''ASP se charge de la conversion, de la signature et de la livraison, mais cette répartition des tâches signifie que le choix du bon ASP compte réellement.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'United Arab Emirates' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Processus d''accréditation des ASP', '[["1. Candidature", "Soumise via le portail du MoF"], ["2-3. Tests", "Contrôles d''interopérabilité préalables à l''approbation, puis tests de bout en bout en production"], ["4. Certification", "Certificat ISO, assurance et vérification de conformité"], ["5. Justificatif", "Émission du certificat PKI Peppol"], ["6. Accréditation", "Accordée pour 2 ans, renouvelable"]]', 'Vérifiez toujours l''accréditation d''un prestataire directement dans le registre public officiel du MoF — ne vous fiez pas à la seule allégation marketing d''accréditation d''un prestataire.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'United Arab Emirates' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Aucun téléversement direct sur le portail de la FTA', '[["Modèle", "Décentralisé — les factures transitent via Peppol/ASP, jamais directement vers un portail gouvernemental"]]', 'C''est le contraste déterminant avec l''Arabie saoudite voisine : il n''existe aucun portail de contrôle gouvernemental sur lequel téléverser — tout passe par votre prestataire de services accrédité.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'United Arab Emirates' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Identifique y verifique un ASP acreditado', 'Consulte directamente el registro público oficial del MoF para confirmar la conectividad con Peppol y el estado de acreditación vigente antes de firmar nada.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'United Arab Emirates' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Priorice la integración con el ERP y el mapeo de datos', 'Mapee sus datos de facturación a las estructuras PINT AE / UBL — este es un trabajo fundamental que debe realizarse independientemente del ASP que elija.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'United Arab Emirates' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Diseñe una integración de API estable con su ASP', 'Construya una conexión resiliente con la infraestructura de facturación electrónica de los EAU en lugar de una solución puntual frágil — es una infraestructura de la que dependerá de forma continua, no una presentación única.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'United Arab Emirates' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Pruebe pronto y por etapas', 'Desarrolle casos de prueba estructurados que cubran facturas, notas de crédito, cancelaciones y escenarios de IVA inusuales (inversión del sujeto pasivo, suministros en zona franca) — no espere a tener un producto terminado para empezar a probar.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'United Arab Emirates' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Establezca una gobernanza interna', 'Defina la propiedad de los datos maestros, los procedimientos de flujo de trabajo de excepciones, la política de archivado y el seguimiento del cumplimiento — son decisiones organizativas que su ASP no puede tomar por usted.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'United Arab Emirates' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Cumpla el plazo de nombramiento del ASP con margen', 'Grandes empresas: nombren a su ASP con suficiente antelación al 30 de octubre de 2026. La incorporación tardía o de emergencia de un ASP conlleva un sobrecoste real por encima de la tarifa estándar de implementación.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'United Arab Emirates' AND ds.sort_order = 5;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Identifizieren und verifizieren Sie einen akkreditierten ASP', 'Prüfen Sie direkt im offiziellen öffentlichen Register des MoF die Peppol-Konnektivität und den aktuellen Akkreditierungsstatus, bevor Sie etwas unterzeichnen.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'United Arab Emirates' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Priorisieren Sie ERP-Integration und Daten-Mapping', 'Ordnen Sie Ihre Rechnungsdaten den PINT-AE-/UBL-Strukturen zu — dies ist grundlegende Arbeit, die unabhängig davon erfolgen muss, welchen ASP Sie wählen.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'United Arab Emirates' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Entwerfen Sie eine stabile API-Integration mit Ihrem ASP', 'Bauen Sie eine belastbare Verbindung zur E-Invoicing-Infrastruktur der VAE auf, statt einer fragilen Insellösung — dies ist eine Infrastruktur, auf die Sie dauerhaft angewiesen sein werden, keine einmalige Einreichung.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'United Arab Emirates' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Testen Sie früh, in Etappen', 'Entwickeln Sie strukturierte Testfälle für Rechnungen, Gutschriften, Stornierungen und ungewöhnliche Mehrwertsteuerszenarien (Reverse Charge, Freizonenlieferungen) — warten Sie nicht auf ein fertiges Produkt, um mit dem Testen zu beginnen.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'United Arab Emirates' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Etablieren Sie eine interne Governance', 'Legen Sie die Verantwortung für Stammdaten, Ausnahme-Workflow-Verfahren, Archivierungsrichtlinien und Compliance-Überwachung fest — dies sind organisatorische Entscheidungen, die Ihr ASP nicht für Sie treffen kann.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'United Arab Emirates' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Halten Sie die ASP-Bestellfrist mit Puffer ein', 'Großunternehmen: Bestellen Sie deutlich vor dem 30. Oktober 2026. Verspätetes oder eiliges ASP-Onboarding ist mit einem echten Kostenaufschlag über den Standard-Implementierungssatz hinaus verbunden.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'United Arab Emirates' AND ds.sort_order = 5;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Identifiez et vérifiez un ASP accrédité', 'Consultez directement le registre public officiel du MoF pour confirmer la connectivité Peppol et le statut d''accréditation actuel avant de signer quoi que ce soit.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'United Arab Emirates' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Priorisez l''intégration ERP et la correspondance des données', 'Faites correspondre vos données de facturation aux structures PINT AE / UBL — il s''agit d''un travail fondamental qui doit être réalisé quel que soit l''ASP choisi.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'United Arab Emirates' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Concevez une intégration API stable avec votre ASP', 'Construisez une connexion résiliente à l''infrastructure de facturation électronique des EAU plutôt qu''une solution ponctuelle fragile — il s''agit d''une infrastructure dont vous dépendrez en continu, pas d''un dépôt ponctuel.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'United Arab Emirates' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Testez tôt, par étapes', 'Élaborez des cas de test structurés couvrant les factures, avoirs, annulations et scénarios de TVA inhabituels (autoliquidation, livraisons en zone franche) — n''attendez pas d''avoir un produit fini pour commencer à tester.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'United Arab Emirates' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Établissez une gouvernance interne', 'Définissez la propriété des données de référence, les procédures de flux de travail des exceptions, la politique d''archivage et le suivi de la conformité — ce sont des décisions organisationnelles que votre ASP ne peut pas prendre à votre place.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'United Arab Emirates' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Respectez l''échéance de désignation de l''ASP avec de la marge', 'Grandes entreprises : désignez votre ASP bien avant le 30 octobre 2026. Une intégration ASP tardive ou d''urgence entraîne un réel surcoût par rapport au tarif d''implémentation standard.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'United Arab Emirates' AND ds.sort_order = 5;

INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'es', 'No implementar el sistema / no nombrar ASP a tiempo', 'AED 5.000 al mes (acumulativo)', NULL FROM deep_dive_penalty_rows pr JOIN countries co ON co.id = pr.country_id WHERE co.name_en = 'United Arab Emirates' AND pr.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'es', 'No emitir/transmitir una factura electrónica a tiempo', 'AED 100 por factura, limitado a AED 5.000/mes', NULL FROM deep_dive_penalty_rows pr JOIN countries co ON co.id = pr.country_id WHERE co.name_en = 'United Arab Emirates' AND pr.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'es', 'No emitir/transmitir una nota de crédito electrónica a tiempo', 'AED 100 por nota, limitado a AED 5.000/mes', NULL FROM deep_dive_penalty_rows pr JOIN countries co ON co.id = pr.country_id WHERE co.name_en = 'United Arab Emirates' AND pr.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'es', 'El emisor no notifica a la FTA un fallo del sistema', 'AED 1.000 por día (sin límite, acumulativo)', NULL FROM deep_dive_penalty_rows pr JOIN countries co ON co.id = pr.country_id WHERE co.name_en = 'United Arab Emirates' AND pr.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'es', 'El receptor no notifica a la FTA un fallo del sistema', 'AED 1.000 por día (sin límite, acumulativo)', NULL FROM deep_dive_penalty_rows pr JOIN countries co ON co.id = pr.country_id WHERE co.name_en = 'United Arab Emirates' AND pr.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'es', 'No notificar al ASP los cambios de datos', 'AED 1.000 por día (sin límite, acumulativo)', NULL FROM deep_dive_penalty_rows pr JOIN countries co ON co.id = pr.country_id WHERE co.name_en = 'United Arab Emirates' AND pr.sort_order = 5;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'de', 'Versäumnis, das System einzuführen / rechtzeitig einen ASP zu bestellen', 'AED 5.000 pro Monat (kumulativ)', NULL FROM deep_dive_penalty_rows pr JOIN countries co ON co.id = pr.country_id WHERE co.name_en = 'United Arab Emirates' AND pr.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'de', 'Versäumnis, eine E-Rechnung rechtzeitig auszustellen/zu übermitteln', 'AED 100 pro Rechnung, gedeckelt bei AED 5.000/Monat', NULL FROM deep_dive_penalty_rows pr JOIN countries co ON co.id = pr.country_id WHERE co.name_en = 'United Arab Emirates' AND pr.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'de', 'Versäumnis, eine elektronische Gutschrift rechtzeitig auszustellen/zu übermitteln', 'AED 100 pro Gutschrift, gedeckelt bei AED 5.000/Monat', NULL FROM deep_dive_penalty_rows pr JOIN countries co ON co.id = pr.country_id WHERE co.name_en = 'United Arab Emirates' AND pr.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'de', 'Aussteller versäumt es, die FTA über einen Systemausfall zu informieren', 'AED 1.000 pro Tag (ungedeckelt, kumulativ)', NULL FROM deep_dive_penalty_rows pr JOIN countries co ON co.id = pr.country_id WHERE co.name_en = 'United Arab Emirates' AND pr.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'de', 'Empfänger versäumt es, die FTA über einen Systemausfall zu informieren', 'AED 1.000 pro Tag (ungedeckelt, kumulativ)', NULL FROM deep_dive_penalty_rows pr JOIN countries co ON co.id = pr.country_id WHERE co.name_en = 'United Arab Emirates' AND pr.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'de', 'Versäumnis, den ASP über Datenänderungen zu informieren', 'AED 1.000 pro Tag (ungedeckelt, kumulativ)', NULL FROM deep_dive_penalty_rows pr JOIN countries co ON co.id = pr.country_id WHERE co.name_en = 'United Arab Emirates' AND pr.sort_order = 5;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'fr', 'Défaut de mise en œuvre du système / de désignation de l''ASP dans les délais', '5 000 AED par mois (cumulatif)', NULL FROM deep_dive_penalty_rows pr JOIN countries co ON co.id = pr.country_id WHERE co.name_en = 'United Arab Emirates' AND pr.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'fr', 'Défaut d''émission/transmission d''une facture électronique dans les délais', '100 AED par facture, plafonné à 5 000 AED/mois', NULL FROM deep_dive_penalty_rows pr JOIN countries co ON co.id = pr.country_id WHERE co.name_en = 'United Arab Emirates' AND pr.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'fr', 'Défaut d''émission/transmission d''une note de crédit électronique dans les délais', '100 AED par note, plafonné à 5 000 AED/mois', NULL FROM deep_dive_penalty_rows pr JOIN countries co ON co.id = pr.country_id WHERE co.name_en = 'United Arab Emirates' AND pr.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'fr', 'L''émetteur omet de notifier une panne du système à la FTA', '1 000 AED par jour (non plafonné, cumulatif)', NULL FROM deep_dive_penalty_rows pr JOIN countries co ON co.id = pr.country_id WHERE co.name_en = 'United Arab Emirates' AND pr.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'fr', 'Le destinataire omet de notifier une panne du système à la FTA', '1 000 AED par jour (non plafonné, cumulatif)', NULL FROM deep_dive_penalty_rows pr JOIN countries co ON co.id = pr.country_id WHERE co.name_en = 'United Arab Emirates' AND pr.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'fr', 'Défaut de notification à l''ASP des changements de données', '1 000 AED par jour (non plafonné, cumulatif)', NULL FROM deep_dive_penalty_rows pr JOIN countries co ON co.id = pr.country_id WHERE co.name_en = 'United Arab Emirates' AND pr.sort_order = 5;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '🕊️ Participantes voluntarios exentos', NULL, NULL, 'Las empresas que usan el sistema voluntariamente durante la fase piloto no están sujetas a estas sanciones hasta que queden obligatoriamente sujetas a la facturación electrónica — una ventana genuinamente libre de riesgo para probar.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'United Arab Emirates' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '⚠️ Doble exposición sancionadora', NULL, NULL, 'Los fallos de facturación electrónica también pueden desencadenar sanciones fiscales más amplias bajo la Decisión del Gabinete n.º 129 de 2025 — por ejemplo, las lagunas en los datos de factura que provocan cifras incorrectas en la declaración de IVA conllevan sus propias sanciones porcentuales independientes, además de las multas de la CD 106.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'United Arab Emirates' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '📦 Períodos de conservación', NULL, NULL, 'Cinco años a efectos de IVA en general; cinco años desde el final del año natural para las empresas no registradas a efectos del IVA; siete años específicamente para los registros inmobiliarios. No conservar los datos en un formato recuperable y accesible para la FTA conlleva su propia sanción independiente bajo la Ley de Procedimientos Fiscales.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'United Arab Emirates' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '🕊️ Freiwillige Teilnehmer ausgenommen', NULL, NULL, 'Unternehmen, die das System während der Pilotphase freiwillig nutzen, unterliegen diesen Bußgeldern nicht, bis sie verpflichtend zur E-Rechnungsstellung verpflichtet sind — ein echtes risikofreies Testfenster.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'United Arab Emirates' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '⚠️ Doppelte Bußgeldexposition', NULL, NULL, 'E-Invoicing-Verstöße können auch breitere Steuerverstoß-Bußgelder nach Kabinettsbeschluss Nr. 129 von 2025 auslösen — beispielsweise ziehen Rechnungsdatenlücken, die zu ungenauen Mehrwertsteuererklärungswerten führen, ihre eigenen separaten prozentualen Bußgelder zusätzlich zu den CD-106-Bußgeldern nach sich.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'United Arab Emirates' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '📦 Aufbewahrungsfristen', NULL, NULL, 'Grundsätzlich fünf Jahre für Mehrwertsteuerzwecke; fünf Jahre ab Ende des Kalenderjahres für nicht umsatzsteuerlich registrierte Unternehmen; sieben Jahre speziell für Immobiliendatensätze. Die Nichtaufbewahrung von Daten in einem abrufbaren, für die FTA zugänglichen Format zieht ein eigenes, separates Bußgeld nach dem Steuerverfahrensgesetz nach sich.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'United Arab Emirates' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '🕊️ Participants volontaires exemptés', NULL, NULL, 'Les entreprises utilisant le système volontairement pendant la phase pilote ne sont pas soumises à ces sanctions tant qu''elles ne sont pas obligatoirement assujetties à la facturation électronique — une fenêtre de test véritablement sans risque.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'United Arab Emirates' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '⚠️ Double exposition aux sanctions', NULL, NULL, 'Les manquements en matière de facturation électronique peuvent également déclencher des sanctions fiscales plus larges en vertu de la décision du Cabinet n° 129 de 2025 — par exemple, des lacunes dans les données de facture entraînant des montants de déclaration de TVA inexacts entraînent leurs propres sanctions distinctes basées sur un pourcentage, en plus des amendes de la CD 106.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'United Arab Emirates' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '📦 Durées de conservation', NULL, NULL, 'Cinq ans à des fins de TVA en général ; cinq ans à compter de la fin de l''année civile pour les entreprises non immatriculées à la TVA ; sept ans spécifiquement pour les registres immobiliers. Le défaut de conservation des données dans un format récupérable et accessible à la FTA entraîne sa propre sanction distincte en vertu de la loi sur les procédures fiscales.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'United Arab Emirates' AND dc.section = 'penalties_related' AND dc.sort_order = 2;

