INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'fr', 'Ministère des Finances des EAU — Facturation électronique' FROM deep_dive_portals dp JOIN countries co ON co.id = dp.country_id WHERE co.name_en = 'United Arab Emirates' AND dp.sort_order = 0;
